package in.rkgitm.hub.security;
import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig{private final JwtFilter jwt;public SecurityConfig(JwtFilter jwt){this.jwt=jwt;}@Bean SecurityFilterChain filter(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/api/achievements/public").permitAll().requestMatchers(org.springframework.http.HttpMethod.POST,"/api/achievements").permitAll().requestMatchers("/api/achievements/pending","/api/achievements/*/status").hasAnyRole("FACULTY","ADMIN").anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}}